(()=>{let storageKey=`spa_privacy_notice_seen_v1`;function inicializarAvisoPrivacidade(){let aviso=document.getElementById(`aviso-cookies`),botao=document.getElementById(`aviso-cookies-fechar`);if(!(!aviso||!botao)){try{window.localStorage.getItem(storageKey)===`1`&&(aviso.hidden=!0)}catch{}botao.addEventListener(`click`,()=>{aviso.hidden=!0;try{window.localStorage.setItem(storageKey,`1`)}catch{}})}}document.readyState===`loading`?document.addEventListener(`DOMContentLoaded`,inicializarAvisoPrivacidade,{once:!0}):inicializarAvisoPrivacidade()})();